use super::*;
#[test]fn actual_raw_record_restore_preserves_warm_fields_and_saved_timer(){let mut b=std::array::from_fn(|i|(i*13+19)as u8);b[4]=1;raw_set(&mut b,28,1000);raw_set(&mut b,80,5);let warm=b[87];trail::restore_raw(&mut b,false,||panic!("vehicle no RNG"),||panic!("vehicle no CRT"));trail::restore_tail(&mut b,0x12345678);assert_eq!(raw_word(&b,30),1000);assert_eq!(b[7],255);assert_eq!(b[87],warm);assert_eq!(i32::from_le_bytes(b[76..80].try_into().unwrap()),8500);assert_eq!(raw_ptr(&b,32),0x12345678);}

fn campaign(mission:usize)->(Game,Value){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../dist/original/campaign.json");let v:Value=serde_json::from_slice(&std::fs::read(p).unwrap()).unwrap();let m=v["missions"][mission].clone();let mut g=Game::new(0,1,433);g.apply_original(&m).unwrap();g.ai_teams.clear();g.units.clear();g.objects.clear();for o in &mut g.native_world.as_mut().unwrap().objects{*o=None;} (g,m)}
fn destroy(g:&mut Game,slot:usize){let(p,id)= {let b=&g.native_world.as_ref().unwrap().buildings[slot];(b.record.position,b.binding.unwrap())};g.buildings.iter_mut().find(|b|b.id==id).unwrap().hp=1.;g.native_blast_environment(i32::from(p[0]),i32::from(p[1]),255,0,false);assert_eq!(g.native_world.as_ref().unwrap().buildings[slot].record.hp,0);}
#[test]#[ignore="private GOG campaign; run explicit asset diagnostic"]fn actual_two_destructions_alias_the_fixed_header_and_full_pool_keeps_rng_and_warm_arena(){
 let(mut g,_)=campaign(0);let slots=g.native_world.as_ref().unwrap().buildings.iter().enumerate().filter(|(_,b)|b.record.kind==4).map(|(i,_)|i).take(2).collect::<Vec<_>>();assert_eq!(slots.len(),2);destroy(&mut g,slots[0]);let w=g.native_world.as_ref().unwrap();let first=w.effects.iter().position(|p|p.as_ref().is_some_and(|p|p.owner==4)).unwrap();let saved=w.effects[first].as_ref().unwrap().bytes();let header=w.trail.headers[slots[0]].unwrap();assert_eq!(u32::from_le_bytes(saved[40..44].try_into().unwrap()),header);
 destroy(&mut g,slots[1]);let w=g.native_world.as_ref().unwrap();assert_eq!(w.trail.headers[slots[1]],Some(header));assert_eq!(w.effects[first].as_ref().unwrap().bytes(),saved,"new destruction does not retarget old raw records");assert_eq!(w.trail.word(header+2).unwrap(),w.buildings[slots[1]].record.position[0]);
 let mut raw=[137u8;44];raw[0..2].copy_from_slice(&5i16.to_le_bytes());let busy=Particle::from_bytes(raw);let w=g.native_world.as_mut().unwrap();w.effects.fill(Some(busy));w.trail.write(header+12,&[11,22,33]).unwrap();let rng=g.original_rng.words;let mut w=g.native_world.take().unwrap();g.native_building_particle_prefix(&mut w,slots[0]);assert_eq!(g.original_rng.words,rng,"full pool fails before constructor RNG");assert_eq!(w.trail.read(header+12,3).unwrap(),[11,22,33]);assert_eq!(w.effects[first].as_ref().unwrap().bytes(),raw);assert_eq!(w.bridge_fx.payload36,header+12+23*10);g.native_world=Some(w);
}
#[test]#[ignore="private GOG campaign; run explicit asset diagnostic"]fn expiry3_live_reentry_uses_new_build_globals_and_does_not_free_source_for_children(){
 let(mut g,_)=campaign(0);let slot=g.native_world.as_ref().unwrap().buildings.iter().position(|b|b.record.kind==4).unwrap();let(p,id)={let b=&g.native_world.as_ref().unwrap().buildings[slot];(b.record.position,b.binding.unwrap())};g.buildings.iter_mut().find(|b|b.id==id).unwrap().hp=1.;let mut raw=[0u8;44];raw[0..2].copy_from_slice(&1i16.to_le_bytes());raw[6..8].copy_from_slice(&p[0].to_le_bytes());raw[8..10].copy_from_slice(&p[1].to_le_bytes());raw[17]=4;raw[20..22].copy_from_slice(&3i16.to_le_bytes());raw[32]=99;let s=g.native_world.as_mut().unwrap();s.effects.fill(None);s.put_effect(0,Particle::from_bytes(raw));s.last_projection=[0,0];s.effect_maximum=91;s.effect_tint=73;s.effect_world_suppression=0;
 g.native_feedback.sound_enabled=0;g.finish_native_building_part_expiry(0,effects::View{camera:[0,0],clip:[0,0,2048,2048],world:[2048,2048],sine:0,cosine:0});let s=g.native_world.as_ref().unwrap();assert_eq!(s.buildings[slot].record.hp,0);assert_eq!(s.trail.headers[slot],Some(trail::BASE));assert_eq!(s.effects[0].as_ref().unwrap().position[0],-1000);assert_eq!(s.effects[0].as_ref().unwrap().raw_tail[0],99,"source slot was not recycled by reentrant BUILD prefix or children");let children=s.effects.iter().enumerate().filter_map(|(i,p)|p.as_ref().filter(|p|p.active&&p.sprite==250).map(|p|(i,p))).collect::<Vec<_>>();assert_eq!(children.len(),4);for(i,p)in children{assert!(i>23);assert_eq!(p.owner,0);assert_eq!(p.flags,4);assert_eq!(p.tint,s.effect_tint,"live reentry changes tint; never restore precontact73");assert_ne!(p.tint,73);assert_eq!(p.raw_tail[0],23);assert_eq!(u32::from_le_bytes(p.raw_tail[8..12].try_into().unwrap()),trail::BASE);assert_eq!(u32::from_le_bytes(p.raw_tail[4..8].try_into().unwrap()),trail::BASE+12+23*10);assert_eq!(p.maximum_phase,s.effect_maximum);}
 assert_eq!(s.effect_world_suppression,0);assert!(g.native_blast_sound_gate,"401640 consumes the shared gate even with audio disabled");let before=g.native_audio.effect_counter;g.native_fragment_zero_blast(p);assert_eq!(g.native_audio.effect_counter,before,"420200 sees the same4d18ee gate");g.update_native_world_effects();assert!(g.native_blast_sound_gate,"500-slot pass must not reset Main gate");
}
#[test]#[ignore="private GOG campaign; run explicit asset diagnostic"]fn mission_reset_retires_raw_x_only_preserves_shared_arenas_and_clears_whole_jobs(){let(mut g,m)=campaign(0);let s=g.native_world.as_mut().unwrap();let mut raw=std::array::from_fn(|n|(n*9+7)as u8);raw[0..2].copy_from_slice(&123i16.to_le_bytes());s.put_effect(400,Particle::from_bytes(raw));s.effect_cp_tints[400]=Some(1);s.trail.arena.fill(71);for j in &mut s.trail.jobs{j.0.fill(99);}s.bridge_fx.byte32=207;s.bridge_fx.payload36=0x12345678;s.effect_world_suppression=1;s.effect_world_mask4f=23;g.import_native_world(&m);let s=g.native_world.as_ref().unwrap();let mut expected=raw;expected[0..2].copy_from_slice(&(-1000i16).to_le_bytes());assert_eq!(s.effects[400].as_ref().unwrap().bytes(),expected);assert!(s.trail.arena.iter().all(|b|*b==71));assert!(s.trail.jobs.iter().all(|j|j.0==[0;24]));assert!(s.effect_cp_tints.iter().all(Option::is_none));assert_eq!(s.bridge_fx.byte32,207);assert_eq!(s.bridge_fx.payload36,0x12345678);assert_eq!(s.effect_world_mask4f,23,"460430 does not reset4a6f4f");}
#[test]#[ignore="private GOG campaign; run explicit asset diagnostic"]fn late_reader_emits_1472_rows_and_retains_early_build_picture_through_restore(){
 let(mut g,_)=campaign(0);let slot=g.native_world.as_ref().unwrap().buildings.iter().position(|b|b.record.kind==4).unwrap();destroy(&mut g,slot);g.begin_native_display_frame();g.capture_native_building_display();let early=g.native_display_queue();let h=trail::BASE;let s=g.native_world.as_mut().unwrap();s.trail.put_word(h,23).unwrap();for(a,n)in[(6,112),(8,912)]{s.trail.put_word(h+a,n).unwrap();}for frame in[1u32,2]{for r in 0..23{let a=h+12+(frame*23+r)*10;let mut b=[0u8;10];b[..2].copy_from_slice(&(120i16+r as i16).to_le_bytes());b[2..4].copy_from_slice(&920i16.to_le_bytes());b[4..6].copy_from_slice(&1782i16.to_le_bytes());s.trail.write(a,&b).unwrap();}}let mut j=trail::Job([0;24]);j.set_ptr(0,h);j.set_ptr(4,BUILD+slot as u32*88);j.set(8,112);j.set(10,912);j.0[12]=3;s.trail.jobs.fill(j);
 g.update_native_building_trails(1);assert!(g.native_building_trail_draws().is_empty());assert!(g.native_world.as_ref().unwrap().trail.jobs.iter().all(|j|j.0[12]==3));g.update_native_building_trails(0);let rows=g.native_building_trail_draws();assert_eq!(rows.len(),64*23);assert!(rows.iter().all(|r|r["nativeInheritedPalette"]==true&&r.get("team").is_none()&&r["stage"]=="late"));if std::env::var_os("Z_TRAIL_ROWS").is_some(){println!("TRAIL_ROWS {}",json!(rows));}g.update_native_building_trails(0);assert!(g.native_world.as_ref().unwrap().buildings[slot].record.hp>0);assert_eq!(g.native_display_queue(),early,"450260 late restore cannot rewrite captured40ad60 artwork");assert!(g.native_world.as_ref().unwrap().trail.jobs.iter().all(|j|j.ptr(0)==0));
}

#[test]#[ignore="private GOG campaign; run explicit asset diagnostic"]fn full_pool_expiry3_keeps_source_occupied_until_all_four_failed_attempts(){let(mut g,_)=campaign(0);let mut raw=std::array::from_fn(|i|(i*13+29)as u8);raw[..2].copy_from_slice(&0i16.to_le_bytes());raw[6..8].copy_from_slice(&(-100i16).to_le_bytes());raw[8..10].copy_from_slice(&500i16.to_le_bytes());let s=g.native_world.as_mut().unwrap();s.effects.fill(Some(Particle::from_bytes(raw)));s.last_projection=[0,0];let rng=g.original_rng.words;g.finish_native_building_part_expiry(0,effects::View{camera:[0,0],clip:[0,0,2048,2048],world:[2048,2048],sine:0,cosine:0});let s=g.native_world.as_ref().unwrap();let mut expected=raw;expected[..2].copy_from_slice(&(-1000i16).to_le_bytes());assert_eq!(s.effects[0].as_ref().unwrap().bytes(),expected);assert!(s.effects[1..].iter().all(|p|p.as_ref().unwrap().bytes()==raw));assert_eq!(g.original_rng.words,rng);}
